# Novedades de la 0.0.5: menú Biblioteca, lista de pacientes (Puntuar hoy, archivar, orden), puntuar con el teclado,
# días de la semana en las pautas, plantillas (nueva y «todo el plan»), ejercicios nuevos, leyenda de líneas,
# informe con resumen por ejercicio y cabecera de la clínica, cabecera compacta y «Salir».
# Uso: python3 mock_server.py PUERTO seed_nuevo.json & ; python3 test_005.py PUERTO
import json, os, re, subprocess, sys, urllib.request
from playwright.sync_api import sync_playwright
PORT = sys.argv[1]; BASE = f'http://127.0.0.1:{PORT}'
fails = []
def check(c, m):
    print(('  ok  ' if c else '  FALLA ') + m)
    if not c: fails.append(m)
get = lambda p: json.loads(urllib.request.urlopen(BASE + p).read())
st = lambda: get('/__state'); stats = lambda: get('/__stats')

with sync_playwright() as pw:
    b = pw.chromium.launch(); page = b.new_page(viewport={'width': 1300, 'height': 900})
    errs = []; page.on('pageerror', lambda e: errs.append(str(e)))
    dialogs = []; page.on('dialog', lambda d: (dialogs.append(d.message), d.accept()))
    page.goto(BASE + '/'); page.wait_for_selector('#listaPacientes'); page.wait_for_timeout(300)
    page.evaluate("descartarNovedades()")
    hoy = page.evaluate('todayIso()'); hoy_fmt = page.evaluate('fmt(todayIso())')

    print('\n[1] Menú principal')
    check(page.locator('nav > button, nav > .menu-sub > button').all_inner_texts() == ['Pacientes', 'Agenda', 'Biblioteca ▾', 'Ajustes', 'Ayuda', 'Salir', ''], 'menú: Pacientes · Agenda · Biblioteca ▾ · Ajustes · Ayuda · Salir')
    page.get_by_role('button', name='Biblioteca', exact=True).click()
    check(page.locator('#menuBiblioteca .submenu button').all_inner_texts() == ['Ejercicios', 'Bloques', 'Plantillas casa'], 'Biblioteca agrupa Ejercicios, Bloques y Plantillas')
    page.keyboard.press('Escape')
    v = page.locator('header .version').bounding_box(); t_ = page.locator('#btnTema').bounding_box(); s_ = page.get_by_role('button', name='Salir', exact=True).bounding_box()
    check(v and v['x'] > t_['x'] > s_['x'] and abs((v['y'] + v['height'] / 2) - (s_['y'] + s_['height'] / 2)) < 6, 'la versión va en la barra de menú, a la derecha de todo (tras el botón de modo)')
    check(page.get_attribute('#btnTema', 'aria-label') == 'Cambiar a modo oscuro', 'botón de modo en la barra')
    page.click('#btnTema'); page.wait_for_timeout(400)
    check(page.evaluate("document.documentElement.dataset.theme") == 'dark' and st()['ajustes'].get('tema') == 'oscuro' and page.get_attribute('#btnTema', 'aria-label') == 'Cambiar a modo claro', 'un clic pasa a modo oscuro y se guarda')
    page.evaluate("ui.ajTab = 'personalizar'; go('ajustes')"); page.wait_for_timeout(100)
    check(page.input_value('#pTema') == 'oscuro', 'Ajustes muestra el mismo modo')
    page.click('#btnTema'); page.wait_for_timeout(300)
    check(page.evaluate("document.documentElement.dataset.theme") == 'light' and page.input_value('#pTema') == 'claro', 'otro clic vuelve a claro (también en Ajustes)')
    page.evaluate("go('pacientes')"); page.wait_for_timeout(100)

    print('\n[2] Lista de pacientes')
    fila = page.locator('#listaPacientes .fila-pac', has_text='López Pérez')
    check('Hoy: 0 de 3 puntuados' in fila.inner_text() and fila.locator('[title="Sin sesiones puntuadas"]').count() == 1, f'cada paciente muestra lo de hoy y su última sesión ({fila.inner_text()!r})')
    check(page.locator('#accionesPac button').all_inner_texts() == ['Nuevo paciente'], 'sin marcar a nadie solo se ve «Nuevo paciente»')
    fila.get_by_role('button', name='Puntuar hoy').click(); page.wait_for_selector('#modal #secPun .rep-fila')
    check(page.evaluate('ui.view') == 'pacientes' and page.evaluate('ui.selDay') == hoy and page.evaluate('ui.patientId') == 'p1', '«Puntuar hoy» abre la ventana de hoy sin salir de la lista')
    check(page.locator('#modal').get_by_role('button', name='Ver su calendario').count() == 1, 'la ventana ofrece «Ver su calendario»')
    filas = page.locator('#modal #secPun .rep-fila')
    check(filas.count() == 3 and filas.nth(0).get_attribute('class').count('foco') == 1, 'la primera fila sin puntuar queda marcada para el teclado')

    print('\n[3] Puntuar con el teclado')
    page.keyboard.press('2'); page.wait_for_timeout(150)
    check(page.evaluate(f"db.puntuaciones['p1|{hoy}|e1|1']") == 2, 'pulsar 2 puntúa la fila marcada')
    check('foco' in page.locator('#modal #secPun .rep-fila').nth(1).get_attribute('class'), 'y pasa a la siguiente fila')
    page.keyboard.press('ArrowDown'); page.keyboard.press('ArrowUp'); page.wait_for_timeout(80)
    check('foco' in page.locator('#modal #secPun .rep-fila').nth(1).get_attribute('class'), 'flechas arriba/abajo mueven la fila marcada')
    page.keyboard.press('+'); page.wait_for_timeout(150)
    check(page.locator('#modal .ej-dia[data-eid="e2"] .rep-fila').count() == 2, '«+» añade una repetición al ejercicio marcado')
    check('foco' in page.locator('#modal .ej-dia[data-eid="e2"] .rep-fila').nth(1).get_attribute('class'), 'y la repetición nueva queda marcada')
    page.keyboard.press('3'); page.wait_for_timeout(150)
    check(page.evaluate(f"db.puntuaciones['p1|{hoy}|e2|2']") == 3, 'se puntúa la repetición nueva')
    page.locator('#modal .modalx').click(); page.wait_for_timeout(500)
    check(page.evaluate('ui.view') == 'pacientes' and 'Hoy: 2 de 3' in page.locator('#listaPacientes .fila-pac', has_text='López Pérez').inner_text(), 'al cerrar se sigue en la lista, ya actualizada')
    page.locator('#listaPacientes .fila-pac', has_text='López Pérez').get_by_role('button', name='Puntuar hoy').click(); page.wait_for_selector('#modal #secPun')
    page.locator('#modal').get_by_role('button', name='Ver su calendario').click(); page.wait_for_timeout(300)
    check(page.evaluate('ui.view + ui.tabP') == 'pacientecalendario' and page.locator('#modal').inner_html() == '', '«Ver su calendario» lleva a la ficha, en el calendario')
    page.evaluate(f"openDay('{hoy}')"); page.wait_for_selector('#modal #secPun')
    check(page.locator('#modal').get_by_role('button', name='Ver su calendario').count() == 0, 'desde el propio calendario no se ofrece')
    page.evaluate('closeModal()'); page.evaluate("go('pacientes')"); page.wait_for_timeout(200)
    check(st()['puntuaciones'].get(f'p1|{hoy}|e1|1') == 2, 'las puntuaciones del teclado se guardan en el servidor')

    print('\n[4] Archivar y ordenar pacientes')
    page.evaluate("""() => { db.patients.push({ id: 'p2', nombre: 'Bea', apellidos: 'Abad Ruiz', telefono: '', email: '', fechaAlta: '2026-02-01', foto: '' }); go('pacientes'); }""")
    page.wait_for_timeout(200)
    nombres = lambda: [t.split('\n')[0] for t in page.locator('#listaPacientes .fila-pac a').all_inner_texts()]
    check(nombres() == ['Abad Ruiz, Bea', 'López Pérez, Ana'], f'por defecto, orden por apellidos ({nombres()})')
    page.locator('#listaPacientes .cab-pac').get_by_role('button', name='Última sesión').click(); page.wait_for_timeout(100)
    check(nombres()[0] == 'López Pérez, Ana', 'al pulsar la cabecera «Última sesión», los que no tienen sesión van al final')
    fila = page.locator('#listaPacientes .fila-pac', has_text='López Pérez')
    check(fila.get_by_role('button', name=f'Última sesión: {hoy_fmt}').count() == 1 and 'Hoy: 2 de 3 puntuados' in fila.inner_text(), f'la fila se actualiza ({fila.inner_text()!r})')
    page.locator('#listaPacientes .fila-pac', has_text='Abad Ruiz').locator('input[type=checkbox]').check(); page.wait_for_timeout(100)
    check(page.locator('#accionesPac button').all_inner_texts() == ['Asignar ejercicios (1)', 'Informe de pautas… (1)', 'Archivar (1)', 'Eliminar (1)', 'Nuevo paciente'], 'al marcar aparecen las acciones en lote')
    page.get_by_role('button', name='Archivar (1)').click(); page.wait_for_timeout(500)
    check(any('Archivar a Bea' in d for d in dialogs), 'pide confirmación para archivar')
    check(nombres() == ['López Pérez, Ana'], 'el archivado deja de verse en la lista')
    check([p.get('archivado') for p in st()['patients'] if p['id'] == 'p2'] == [True], 'se guarda «archivado» en el servidor')
    check('Activos (1)' in page.locator('#filtroPac').inner_text() and 'Archivados (1)' in page.locator('#filtroPac').inner_text(), 'el filtro cuenta activos y archivados')
    page.select_option('#filtroPac', 'archivados'); page.wait_for_timeout(100)
    check(nombres() == ['Abad Ruiz, Bea'] and 'Archivado' in page.locator('#listaPacientes').inner_text(), '«Archivados» muestra al paciente con su etiqueta')
    page.locator('#listaPacientes .fila-pac').first.locator('input[type=checkbox]').check()
    page.get_by_role('button', name='Recuperar (1)').click(); page.wait_for_timeout(500)
    check([p.get('archivado') for p in st()['patients'] if p['id'] == 'p2'] == [None], '«Recuperar» lo devuelve a activos')
    page.select_option('#filtroPac', 'activos'); page.evaluate("setAjuste('orden.pacientes', ''); refrescarPacientes()"); page.wait_for_timeout(100)
    # archivar desde la ficha
    page.evaluate("openPatient('p2')"); page.get_by_role('button', name='Editar datos del paciente').click(); page.get_by_role('button', name='Archivar paciente').click(); page.wait_for_timeout(300)
    check(page.locator('#modal').inner_text().strip() == '', 'desde «Editar datos del paciente» se puede archivar')
    check('Paciente archivado.' in page.locator('.sticky-head').inner_text(), 'la ficha de un archivado lo indica, con «Recuperar»')
    page.locator('.sticky-head').get_by_role('button', name='Recuperar').click(); page.wait_for_timeout(300)
    check('Paciente archivado.' not in page.locator('#main').inner_text(), 'y se puede recuperar desde ahí')

    print('\n[5] Pautas: días de la semana')
    page.evaluate("openPatient('p1')"); page.get_by_role('tab', name='Pautas').click(); page.wait_for_timeout(100)
    check('Primera visita: 10/01/2026' in page.locator('.sticky-head').inner_text() or 'Primera visita:' in page.locator('.sticky-head').inner_text(), 'la cabecera dice «Primera visita»')
    page.locator('#sec-pautas .item', has_text='Estiramiento isquios').get_by_role('button', name='Editar', exact=True).click(); page.wait_for_selector('#epDias')
    check(page.locator('#epDias input:checked').count() == 7, 'por defecto, todos los días')
    for d in ['2', '4', '6', '7']: page.locator(f'#epDias input[value="{d}"]').uncheck()
    page.locator('#modal').get_by_role('button', name='Guardar', exact=True).click(); page.wait_for_timeout(300)
    check(page.evaluate("db.pautas.find(p => p.id === 'a3').dias") == '135', 'se guardan lunes, miércoles y viernes')
    check('los lunes, miércoles y viernes' in page.locator('#sec-pautas .item', has_text='Estiramiento isquios').inner_text(), 'la pauta indica sus días')
    check(page.evaluate("exercisesOn('p1', '2026-02-02').some(i => i.exercise.id === 'e3') && !exercisesOn('p1', '2026-02-03').some(i => i.exercise.id === 'e3')"), 'el ejercicio sale el lunes y no el martes')
    page.wait_for_timeout(300)
    check([p.get('dias') for p in st()['pautas'] if p['id'] == 'a3'] == ['135'], 'los días llegan al servidor')
    page.locator('#sec-pautas .item', has_text='Estiramiento isquios').get_by_role('button', name='Editar', exact=True).click(); page.wait_for_selector('#epDias')
    for d in ['1', '3', '5']: page.locator(f'#epDias input[value="{d}"]').uncheck()
    dialogs.clear(); page.locator('#modal').get_by_role('button', name='Guardar', exact=True).click(); page.wait_for_timeout(200)
    check(len(dialogs) == 1 and page.locator('#epDias').count() == 1, 'sin ningún día marcado avisa y no guarda')
    page.locator('#epDias').get_by_role('button', name='Todos').click()
    page.locator('#modal').get_by_role('button', name='Guardar', exact=True).click(); page.wait_for_timeout(200)
    check(not page.evaluate("db.pautas.find(p => p.id === 'a3').dias"), '«Todos» vuelve a todos los días (sin restricción)')
    # asignar con días
    page.locator('#sec-pautas').get_by_role('button', name='Asignar ejercicios').click(); page.wait_for_selector('#aDias')
    page.locator('#modal .exCheck[value="e4"]').check()
    page.locator('#aDias').get_by_role('button', name='Lunes a viernes').click()
    page.locator('#modal').get_by_role('button', name='Asignar', exact=True).click(); page.wait_for_timeout(300)
    check(page.evaluate("db.pautas.filter(p => p.exerciseId === 'e4').map(p => p.dias)") == ['12345'], 'al asignar se pueden elegir los días (lunes a viernes)')

    print('\n[6] Calendario: mes resumido')
    page.get_by_role('tab', name='Calendario').click(); page.evaluate("cambiarVista('mes')"); page.wait_for_timeout(150)
    celda = page.locator('.day.mes.today')
    check(celda.locator('.mes-media').count() == 1 and 'puntuados' in celda.inner_text(), f'la celda de hoy resume media y puntuados ({celda.inner_text()!r})')

    print('\n[7] Resumen: líneas por ejercicio, bloque o media y leyenda')
    page.evaluate("""() => { for (let i = 1; i < 5; i++){ const d = addDays(todayIso(), -i); db.puntuaciones[scoreKey('p1', d, 'e1', 1)] = i % 4; db.puntuaciones[scoreKey('p1', d, 'e3', 1)] = (i + 1) % 4; } idxPunt = null; render(); }""")
    page.locator('#subCal').get_by_role('button', name='Resumen').click(); page.wait_for_timeout(100)
    page.locator('#sec-resumen .tabs:not(#subCal)').first.get_by_role('button', name='Mes', exact=True).click()
    page.get_by_role('button', name='Líneas', exact=True).click(); page.wait_for_timeout(150)
    check(page.locator('#modoLineas button').all_inner_texts() == ['Por ejercicio', 'Por bloque', 'Media del día'], 'modos de la gráfica de líneas')
    n0 = page.locator('#resCuerpo svg path').count()
    page.locator('#resCuerpo .leyenda-lineas .ley').first.click(); page.wait_for_timeout(100)
    check(page.locator('#resCuerpo svg path').count() == n0 - 1 and page.locator('#resCuerpo .ley').first.get_attribute('aria-pressed') == 'false', 'pulsar la leyenda oculta esa línea')
    page.locator('#resCuerpo .leyenda-lineas .ley').first.click(); page.wait_for_timeout(100)
    check(page.locator('#resCuerpo svg path').count() == n0, 'y volver a pulsar la muestra')
    page.locator('#modoLineas').get_by_role('button', name='Media del día').click(); page.wait_for_timeout(100)
    check(page.locator('#resCuerpo svg path').count() == 1, '«Media del día»: una sola línea')

    print('\n[8] Informe PDF: cabecera de la clínica, resumen por ejercicio y detalle opcional')
    page.evaluate("db.ajustes.clinicaNombre = 'Clínica Ría'; db.ajustes.profNombre = 'Marta Gil'; render()")
    page.get_by_role('tab', name='Informes').click(); page.wait_for_timeout(100)
    get('/__dialogo/ok')
    page.get_by_role('button', name='Generar informe de pautas…').click(); page.wait_for_selector('#expDetalle')
    page.locator('#expDetalle').uncheck(); page.click('#expGenerar'); page.wait_for_selector('#expEstado >> text=Guardado', timeout=30000)
    ruta = page.evaluate('db.informes.at(-1).ruta')
    txt = subprocess.run(['pdftotext', '-layout', ruta, '-'], capture_output=True, text=True).stdout
    npag = int(re.search(r'Pages:\s+(\d+)', subprocess.run(['pdfinfo', ruta], capture_output=True, text=True).stdout).group(1))
    check('Clínica Ría' in txt and 'Profesional: Marta Gil' in txt, 'la cabecera lleva la clínica y el profesional')
    check('Resumen por ejercicio' in txt and 'Detalle por días' not in txt and npag == 1, f'sin detalle: solo el resumen ({npag} página)')
    page.locator('#expDetalle').check(); page.click('#expGenerar'); page.wait_for_timeout(300); page.wait_for_selector('#expEstado >> text=Guardado', timeout=30000)
    txt2 = subprocess.run(['pdftotext', '-layout', page.evaluate('db.informes.at(-1).ruta'), '-'], capture_output=True, text=True).stdout
    check('Resumen por ejercicio' in txt2 and 'Detalle por días' in txt2, 'con detalle: resumen y detalle por días')
    page.evaluate('closeModal()')

    print('\n[9] Cabecera compacta al bajar')
    page.get_by_role('tab', name='Calendario').click(); page.evaluate("cambiarVista('mes')"); page.wait_for_timeout(100)
    page.set_viewport_size({'width': 1300, 'height': 520})   # que haya sitio para bajar
    alto = page.locator('.sticky-head').bounding_box()['height']
    page.mouse.move(650, 400); page.mouse.wheel(0, 900); page.wait_for_timeout(300)
    check('compacta' in page.locator('.sticky-head').get_attribute('class') and page.locator('.sticky-head').bounding_box()['height'] < alto, 'al bajar, la cabecera del paciente se compacta')
    page.mouse.wheel(0, -3000); page.wait_for_timeout(300); page.set_viewport_size({'width': 1300, 'height': 900})

    print('\n[10] Biblioteca: nuevo ejercicio, crear desde un bloque y nueva plantilla')
    page.get_by_role('button', name='Biblioteca', exact=True).click(); page.get_by_role('button', name='Ejercicios', exact=True).click(); page.wait_for_timeout(100)
    page.get_by_role('button', name='Nuevo ejercicio…').click(); page.fill('#nuevoEj', 'Sentadilla con apoyo'); page.keyboard.press('Enter'); page.wait_for_timeout(300)
    check('Sentadilla con apoyo' in page.locator('#listaEjercicios').inner_text() and any(e['nombre'] == 'Sentadilla con apoyo' for e in st()['exercises']), 'se crea desde su ventana y se guarda')
    dialogs.clear(); page.get_by_role('button', name='Nuevo ejercicio…').click(); page.fill('#nuevoEj', 'sentadilla con APOYO'); page.keyboard.press('Enter'); page.wait_for_timeout(200)
    check(any('Ya existe' in d for d in dialogs), 'no deja repetir un nombre')
    page.evaluate('closeModal()')
    item = page.locator('#listaEjercicios .item', has_text='Sentadilla con apoyo')
    item.get_by_role('button', name=re.compile('^Acciones de')).click()
    check(item.locator('.submenu button').all_inner_texts() == ['Renombrar…', 'Duplicar', 'Eliminar…'], 'menú ⋯ con Renombrar, Duplicar y Eliminar')
    check('peligro' in (item.locator('.submenu button', has_text='Eliminar…').get_attribute('class') or ''), 'Eliminar va en rojo')
    page.keyboard.press('Escape')
    page.get_by_role('button', name='Biblioteca', exact=True).click(); page.get_by_role('button', name='Bloques', exact=True).click(); page.wait_for_timeout(100)
    check(page.get_by_role('button', name='Importar…').count() == 1 and page.get_by_role('button', name='Exportar…').count() == 1, '«Exportar…» e «Importar…» están en la pantalla Bloques')
    page.get_by_role('button', name='Nuevo bloque').click(); page.wait_for_selector('#bNuevoEj')
    page.fill('#bNombre', 'Equilibrio'); page.fill('#bNuevoEj', 'Apoyo monopodal'); page.get_by_role('button', name='Crear y añadir').click(); page.wait_for_timeout(100)
    check(page.locator('#ordenBloque [data-id]').count() == 1 and 'Apoyo monopodal' in page.locator('#ordenBloque').inner_text(), 'crear un ejercicio desde el bloque lo deja añadido')
    page.locator('#modal').get_by_role('button', name='Guardar', exact=True).click(); page.wait_for_timeout(400)
    s = st(); eid = [e['id'] for e in s['exercises'] if e['nombre'] == 'Apoyo monopodal']
    check(len(eid) == 1 and any(b_['nombre'] == 'Equilibrio' and b_['ejercicios'] == eid for b_ in s['bloques']), 'el ejercicio queda en la biblioteca y en el bloque')
    page.get_by_role('button', name='Biblioteca', exact=True).click(); page.get_by_role('button', name='Plantillas casa', exact=True).click(); page.wait_for_timeout(100)
    page.get_by_role('button', name='Nueva plantilla').click(); page.wait_for_selector('#sec-plantilla'); page.wait_for_timeout(300)
    check(page.evaluate("document.activeElement && document.activeElement.value") == 'Plantilla nueva', 'Nueva plantilla abre su editor con el nombre listo para escribir')
    page.keyboard.type('Equilibrio inicial'); page.keyboard.press('Tab'); page.wait_for_timeout(400)
    check(any(t['nombre'] == 'Equilibrio inicial' for t in st()['plantillas']), 'la plantilla nueva se guarda')

    print('\n[12] Salir')
    dialogs.clear(); page.get_by_role('button', name='Salir', exact=True).click(); page.wait_for_timeout(500)
    check(any('Cerrar la aplicación' in d for d in dialogs), 'pide confirmación')
    check(stats().get('salir') == 1 and 'La aplicación se ha cerrado' in page.locator('body').inner_text(), 'apaga el programa y lo explica en la página')

    check(not errs, f'sin errores JS {errs}')
    b.close()
print('\nRESULTADO:', 'TODO OK' if not fails else f'{len(fails)} FALLOS')
sys.exit(1 if fails else 0)
